Implement an iterator in Python for the following string.

### Input:
string = 'Hello World!'

### Response:
class Iterator:
    def __init__(self, data):
        self.data = data
        self.index = 0

    def __iter__(self):
        return self

    def __next__(self):
        if self.index >= len(self.data):
            raise StopIteration
        char = self.data[self.index]
        self.index += 1
        return char

iterator = Iterator(string)
for char in iterator:
