def nested_set_iteration(set1, set2):

    """
   Given two sets of DNA sequences, set1 and set2, the task is to iterate through both sets simultaneously and find the common elements.
   Return a new set containing the common elements found in both sets.
    """

### Solution:


    common_elements = set()

    # Iterate through the first set
    iterator1 = iter(set1)
    while True:
        try:
            seq1 = next(iterator1)
        except StopIteration:
            break

        # Iterate through the second set
        iterator2 = iter(set2)
        while True:
            try:
                seq2 = next(iterator2)
            except StopIteration:
                break

            # Compare the sequences and add to common_elements if they are the same
            if seq1 == seq2:
                common_elements.add(seq1)

    return common_elements

